/* Reference-based "سفارشی" front, same ID-1 size. Never affect the existing layouts/back. */
.card-custom-only{display:none}
.card-id.custom{border:.3mm solid var(--cp);background:#fff;border-radius:3mm}
.card-id.custom .card-head{height:10mm;padding:0;border:0;color:#fff;background:linear-gradient(90deg,var(--cp),var(--ca))}
.card-id.custom .card-head::after{height:.7mm;background:var(--ca)}
.card-id.custom .card-school{position:absolute;top:1.3mm;right:2.6mm;width:34mm;font-family:var(--f-titr);font-size:3.8mm;line-height:1.2;color:#fff}
.card-id.custom .card-meta{position:absolute;top:5.7mm;right:2.6mm;width:34mm;font-size:1.85mm;line-height:1.2;color:#fff}
.card-id.custom .card-logo,.card-id.custom .card-custom-mark{position:absolute;display:block;top:1.2mm;left:32mm;width:13mm;height:7mm;background:transparent;padding:0;border:0;border-radius:0;object-fit:contain;color:#fff}
.card-id.custom .card-body{top:0;right:0;left:0;bottom:0;padding:0}
.card-id.custom .card-photo,.card-id.custom .card-photo-ph{top:2.4mm;left:3mm;width:22.5mm;height:29mm;border:.4mm solid var(--cp);border-radius:2mm;background:#fff;object-fit:contain;object-position:center;box-shadow:0 0 0 .65mm #fff;z-index:2}
.card-id.custom .card-photo-ph svg{width:14mm;height:18mm;margin:5mm 4mm}
.card-id.custom .card-info{top:34.5mm;left:2.6mm;right:auto;width:37.5mm;text-align:right}
.card-id.custom .card-name{font-family:var(--f-titr);font-size:4.2mm;font-weight:700;line-height:1.3;color:#151b2a;white-space:nowrap;letter-spacing:normal;text-overflow:clip}
.card-id.custom .card-rows{margin-top:.5mm}
.card-id.custom .card-row{font-size:2.4mm;line-height:1.3;white-space:nowrap}
.card-id.custom .card-row b{color:var(--cp)}
.card-id.custom .card-nid{font-size:2.2mm}
.card-id.custom .card-qr-box{top:11.5mm;right:2.6mm;width:40mm}
.card-id.custom .card-qr{width:40mm;height:40mm;background:#fff}
.card-id.custom .card-custom-site{display:block;position:absolute;top:47.2mm;left:2.6mm;width:37.5mm;font-family:Georgia,'Times New Roman',serif;font-size:5mm;font-weight:700;line-height:1.1;color:var(--cp);white-space:nowrap;text-align:right;overflow:hidden}
.card-id.custom .card-foot{top:52mm;bottom:auto;left:auto;right:2.6mm;width:40mm;text-align:center}
.card-id.custom .card-year{font-size:1.25mm;line-height:1;color:#64748b}
.card-id.custom .card-bg,.card-id.custom .card-frame,.card-id.custom .card-hero,.card-id.custom .card-band,.card-id.custom .card-head-orn,.card-id.custom .card-qr-cap,.card-id.custom .card-grade{display:none!important}
